import io, json, platform, sys, unicodedata
class Text(str):
    def __str__(self):
        raise AssertionError('virtual str conversion')
    def __getitem__(self, key):
        raise AssertionError('virtual subscription')
inputs = [[], [65], [65,66], [65,10,66], [65,13,66], [65,13,10,66], [65,13], [13], [13,10], [65,0x010d,66], [65,0x0d00,66], [65,0x0d0000,66], [0xd800,0xdc00], [65,0x010a,66], [0x1f600,10], [13,13]]
histories = [[], [10], [13], [13,10], [13,65,10,13,10]]
groups=[]
for translate in [False,True]:
 for history in histories:
  for pending in [False,True]:
   rows=[]
   for points in inputs:
    for final in [False,True]:
     decoder=io.IncrementalNewlineDecoder(None,translate)
     decoder.decode(''.join(map(chr,history)),True)
     decoder.setstate((b'',int(pending)))
     text=Text(''.join(map(chr,points)))
     result=decoder.decode(text,final)
     rows.append(dict(input=points,final=final,output=list(map(ord,result)),reuse=result is text,kind=type(result).__name__,pending=bool(decoder.getstate()[1]),newlines=decoder.newlines))
   groups.append(dict(translate=translate,history=history,pending=pending,rows=rows))
print(json.dumps(dict(target=dict(version=sys.version,unicode=unicodedata.unidata_version,platform=sys.platform,machine=platform.machine(),byteorder=sys.byteorder),groups=groups),ensure_ascii=True,indent=2))

