import reference from '/Users/kjopek/Workspace/poe-code-3/packages/safe-python/src/runtime/__snapshots__/codec-newline-reuse-3.14.7.json' with {type:'json'};
import {CodePointString} from '/Users/kjopek/Workspace/poe-code-3/packages/safe-python/src/runtime/code-point-string.ts';
import {UniversalNewlineDecoder} from '/Users/kjopek/Workspace/poe-code-3/packages/safe-python/src/runtime/newline-decoder.ts';
import boundaries from '/Users/kjopek/Workspace/poe-code-3/packages/safe-python/src/runtime/__snapshots__/newline-boundaries-3.14.7.json' with {type:'json'};
import {Utf8IncrementalDecoder} from '/Users/kjopek/Workspace/poe-code-3/packages/safe-python/src/runtime/utf8-incremental.ts';
import {ExecutionBudget} from '/Users/kjopek/Workspace/poe-code-3/packages/safe-python/src/runtime/execution-budget.ts';
// External differential evidence: explicit file descriptors belong only to this
// driver. Package kernels receive immutable points and a meter, never host I/O.
const directory=mkdtempSync(join(tmpdir(),'codec-newline-reuse-'));
let reads=0,writes=0,syncs=0,cases=0,reused=0,streamSplits=0;
function store(path:string,text:string|Uint8Array){
 const fd=openSync(path,'w');
 try{const bytes=typeof text==='string'?Buffer.from(text):text;let position=0;while(position<bytes.length){const n=writeSync(fd,bytes,position,Math.min(97,bytes.length-position));assert(n>0);position+=n;writes++;}fsyncSync(fd);syncs++;}finally{closeSync(fd);}
}
function load(path:string){
 const fd=openSync(path,'r');
 try{const parts:Buffer[]=[];for(;;){const part=Buffer.alloc(71);const n=readSync(fd,part,0,part.length,null);reads++;if(n===0)break;parts.push(part.subarray(0,n));}return Buffer.concat(parts).toString('utf8');}finally{closeSync(fd);}
}
try{
 for(const [index,group] of reference.groups.entries()){
  const inputPath=join(directory,`input-${index}`),outputPath=join(directory,`output-${index}`);
  store(inputPath,JSON.stringify(group));
  const received=JSON.parse(load(inputPath)) as typeof group;
  const results=[];
  for(const row of received.rows){
   const meter=new ExecutionBudget({maxSteps:10000,maxAllocatedBytes:100000});
   const points=(items:readonly number[])=>new CodePointString(Uint32Array.from(items),meter);
   const decoder=new UniversalNewlineDecoder(received.translate);
   decoder.decode(points(received.history),true,meter);
   decoder.setstate({pendingCR:received.pending},meter);
   const input=points(row.input),output=decoder.decode(input,row.final,meter);
   const actual={output:[...output],reuse:output===input,pending:decoder.getstate(meter).pendingCR,newlines:decoder.newlines};
   assert.deepEqual(actual,{output:row.output,reuse:row.reuse,pending:row.pending,newlines:row.newlines});
   results.push(actual);cases++;if(actual.reuse)reused++;
  }
  const serialized=JSON.stringify(results);
  store(outputPath,serialized);assert.equal(load(outputPath),serialized);
 }
 for(const [index,row] of boundaries.utf8.entries()){
  const path=join(directory,`utf8-${index}`);
  store(path,Uint8Array.from(row.input));
  for(let split=0;split<=row.input.length;split++){
   const fd=openSync(path,'r');
   try{
    const meter=new ExecutionBudget({maxSteps:10000,maxAllocatedBytes:100000});
    const bytes=new Utf8IncrementalDecoder('surrogatepass'),newline=new UniversalNewlineDecoder(row.translate);
    const events=[];
    for(const [size,final] of [[split,false],[0,false],[row.input.length-split,true],[0,true]] as const){
     const chunk=new Uint8Array(size);let offset=0;
     while(offset<size){const n=readSync(fd,chunk,offset,Math.min(3,size-offset),null);reads++;assert(n>0);offset+=n;}
     const output=newline.decode(bytes.decode(chunk,final,meter),final,meter);
     const [pending,flag]=bytes.getstate(meter);
     events.push([[...output],[...pending],Number(flag*2n)+Number(newline.getstate(meter).pendingCR),newline.newlines]);
    }
    assert.deepEqual(events,row.scenarios[split]);
    const outputPath=join(directory,`utf8-output-${index}-${split}`),serialized=JSON.stringify(events);
    store(outputPath,serialized);assert.equal(load(outputPath),serialized);streamSplits++;
   }finally{closeSync(fd);}
  }
 }
 console.log(JSON.stringify({cases,reused,streamSplits,reads,writes,syncs,target:reference.target}));
}finally{rmSync(directory,{recursive:true});}
